'use strict';
(()=>{let records=[],filtered=[],page=0;const size=25,$=id=>document.getElementById(id);function text(tag,value,parent,cls){const el=document.createElement(tag);el.textContent=value;if(cls)el.className=cls;parent.append(el);return el}function link(label,url,parent){const a=text('a',label,parent);a.href=url;a.target='_blank';a.rel='noopener noreferrer'}
function draw(){const q=$('litQuery').value.toLowerCase().trim(),cat=$('litCategory').value,type=$('litType').value,from=Number($('litFrom').value)||2006,to=Number($('litTo').value)||2026;filtered=records.filter(r=>(!q||r.search.includes(q))&&(!cat||r.categories.includes(cat))&&Number(r.date.slice(0,4)||r.year)>=from&&Number(r.date.slice(0,4)||r.year)<=to&&(!type||(type==='preprint'?r.source==='PPR':type==='review'?r.publication_type.toLowerCase().includes('review'):r.source==='MED')));filtered.sort($('litSort').value==='title'?(a,b)=>a.title.localeCompare(b.title):$('litSort').value==='old'?(a,b)=>a.date.localeCompare(b.date):(a,b)=>b.date.localeCompare(a.date));page=Math.min(page,Math.max(0,Math.ceil(filtered.length/size)-1));$('litCount').textContent=filtered.length.toLocaleString()+' matching records';$('litResults').replaceChildren();for(const r of filtered.slice(page*size,(page+1)*size)){const card=document.createElement('article');card.className='paper';const h=text('h3','',card);link(r.title,r.url,h);text('p',r.authors||'Authors not supplied',card);text('p',[r.year,r.journal||'Journal not supplied',r.source==='PPR'?'Preprint':r.publication_type||'Journal record'].join(' · '),card);text('p',r.categories.join(' · '),card,'tags');text('p','Awaiting relevance screening · '+(r.pmid?'PMID '+r.pmid+' · ':'')+(r.doi?'DOI '+r.doi:'DOI not supplied'),card,'tags');$('litResults').append(card)}$('litPage').textContent=filtered.length?'Page '+(page+1)+' of '+Math.ceil(filtered.length/size):'No matches';$('litPrev').disabled=page===0;$('litNext').disabled=(page+1)*size>=filtered.length;}
function save(name,content,mime){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([content],{type:mime}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csv(v){let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
$('litCSV').onclick=()=>{const keys=['title','authors','year','date','journal','doi','pmid','source','publication_type','categories','status','url'];save('cancer-bioelectricity-filtered.csv',[keys.join(','),...filtered.map(r=>keys.map(k=>csv(Array.isArray(r[k])?r[k].join('; '):r[k])).join(','))].join('\r\n'),'text/csv')};
$('litRIS').onclick=()=>save('cancer-bioelectricity-filtered.ris',filtered.map(r=>['TY  - '+(r.source==='PPR'?'UNPB':'JOUR'),'TI  - '+r.title.replace(/\s+/g,' '),'PY  - '+r.year,'JO  - '+r.journal,'DO  - '+r.doi,'UR  - '+r.url,'N1  - Authors as supplied: '+r.authors,'N1  - Awaiting relevance screening','ER  - '].join('\r\n')).join('\r\n\r\n'),'application/x-research-info-systems');
for(const button of document.querySelectorAll('[data-quick-search]'))button.addEventListener('click',()=>{$('litQuery').value=button.dataset.quickSearch;$('litQuery').dispatchEvent(new Event('input',{bubbles:true}))});
$('litClear').addEventListener('click',()=>{$('litQuery').value='';$('litCategory').value='';$('litType').value='';$('litFrom').value='2006';$('litTo').value='2026';$('litSort').value='new';$('litQuery').dispatchEvent(new Event('input',{bubbles:true}))});
let timer;for(const id of ['litQuery','litCategory','litType','litFrom','litTo','litSort'])$(id).addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{page=0;draw()},150)});$('litPrev').onclick=()=>{page--;draw()};$('litNext').onclick=()=>{page++;draw()};
(async()=>{try{const res=await fetch('literature/search-log.json');if(!res.ok)throw Error('Search log unavailable');const log=await res.json();for(const s of log.searches){const p=text('p',s.category+': '+s.hit_count.toLocaleString()+' hits; '+s.retrieved.toLocaleString()+' downloaded; pagination '+(s.complete_pagination?'complete':'incomplete')+'.',$('coverageList'));const d=document.createElement('details');text('summary','Exact query',d);text('p',s.query,d);$('coverageList').append(d)}const files=log.data_files;let cursor=0,loaded=0;async function worker(){while(cursor<files.length){const file=files[cursor++];const r=await fetch('literature/'+file);if(!r.ok)throw Error('A catalogue file failed to load');records.push(...await r.json());loaded++;$('catalogueStatus').textContent='Loading '+loaded+' / '+files.length+' catalogue files…'}}await Promise.all(Array.from({length:4},worker));records.forEach(r=>r.search=[r.title,r.authors,r.doi,r.pmid].join(' ').toLowerCase());const cats=[...new Set(records.flatMap(r=>r.categories))].sort();for(const c of cats){const o=document.createElement('option');o.value=c;o.textContent=c;$('litCategory').append(o)}$('catalogueStatus').textContent=records.length.toLocaleString()+' deduplicated records · Europe PMC · retrieved '+log.retrieved_at_utc.slice(0,10)+'. Metadata only; full texts are linked, not stored.';$('litCSV').disabled=false;$('litRIS').disabled=false;draw()}catch(e){$('catalogueStatus').textContent='The catalogue could not be loaded. Please refresh. '+e.message}})();})();
